    foreach ($volume in $before.volumes) {
        $budget = $plan.admission.volumeBudgets.PSObject.Properties[$volume.letter].Value
        Assert-Compute ($volume.health -ceq 'Healthy' -and $volume.free -ge $budget.freeFloorBytes -and ($budget.maximumVhdBytes + $budget.runtimeBytes + $budget.metadataBytes + $budget.freeFloorBytes) -le $volume.size) 'Runtime-state/free volume admission failed'
    }
    if ($entry.effect -cin @('drain', 'resume','infrastructure-return','moc-remove','moc-add')) {
        $target = if ($entry.node) { $entry.node } else { 'LB-NODE01' }
        $sessionNode=if($entry.effect -cin @('moc-remove','moc-add')){$mocObserver}else{$target}
        if($entry.effect -cin @('moc-remove','moc-add')){Assert-Compute ($sessionNode -cne $entry.node -and $sessionNode -ceq (Get-ProfileMocPeer $entry.node $before)) 'MOC caller must be exact healthy peer'}
        $session = New-ComputeSession $sessionNode
    }
    if ([DateTimeOffset]::UtcNow -ge [DateTimeOffset]::Parse($plan.executionApproval.expiresAt)) { throw 'GO expired before RPC' }
    Assert-OffconfigFreshAuthority
    $state.rpcInvoked = $true; Save-R2Worker 'rpc-pending'
    try {
        switch -CaseSensitive ($entry.effect) {
            'guest-stop' {
                $stopMoc = Read-ProfileMoc $mocObserver
                Assert-ProfileMocMembership $stopMoc $entry.beforeMocMembers $plan.mocContract
                $stopBefore = Read-ComputeSnapshot
                Assert-ComputeMaintenanceHealth $stopBefore $entry.node $proof $false
                $current = @($stopBefore.clusterHealth.nodeStates | Where-Object name -CEQ $entry.node)
                Assert-Compute ($current.Count -eq 1 -and $current[0].state -ceq 'Paused') 'Graceful stop requires current paused node'
                $devices = @($stopBefore.clusterHealth.devices | Where-Object owner -CEQ $entry.node)
                Assert-Compute ($devices.Count -eq 8 -and @($devices | Where-Object { $_.maintenance -ne $true -or @($_.operational | Where-Object { $_ -cin @('In Maintenance Mode','InMaintenanceMode') }).Count -eq 0 }).Count -eq 0) 'Graceful stop requires current eight-device maintenance'
                if ($entry.node -ceq 'LB-NODE01') { Assert-ProfileInfrastructurePlacement $stopBefore }
                $vm = Get-VM -Id $plan.guestIds.PSObject.Properties[$entry.guest].Value
                if ($vm.Name -cne $entry.guest -or $vm.State.ToString() -cne 'Running') { throw 'Exact Running guest required' }
                if ([DateTimeOffset]::UtcNow -ge [DateTimeOffset]::Parse($plan.executionApproval.expiresAt)) { throw 'GO expired before graceful stop' }
                Stop-VM -VM $vm -Confirm:$false -ErrorAction Stop
            }
            'memory' {
                $vm = Get-VM -Id $plan.guestIds.PSObject.Properties[$entry.node].Value
                if ($vm.Name -cne $entry.node -or $vm.State.ToString() -cne 'Off') { throw 'Memory resize requires independently observed Off' }
                $m=Get-VMMemory -VM $vm
                if ($m.DynamicMemoryEnabled -or $m.Minimum -gt $entry.targetMemoryBytes -or $m.Maximum -lt $entry.targetMemoryBytes) { throw 'Native memory bounds differ' }
                Set-VMMemory -VM $vm -StartupBytes $entry.targetMemoryBytes -ErrorAction Stop
            }
            'cpu' {
                $vm = Get-VM -Id $plan.guestIds.PSObject.Properties[$entry.node].Value
                if ($vm.Name -cne $entry.node -or $vm.State.ToString() -cne 'Off') { throw 'CPU resize requires independently observed Off' }
                $p=Get-VMProcessor -VM $vm
                if (-not $p.ExposeVirtualizationExtensions -or $p.MaximumCountPerNumaNode -lt $entry.targetCpu -or $vm.Generation -ne 2 -or $vm.Version.ToString() -cne '12.0' -or -not (Get-VMHost).NumaSpanningEnabled) { throw 'Native processor/version bounds differ' }
                Set-VMProcessor -VM $vm -Count $entry.targetCpu -ErrorAction Stop
            }
            'drain' {
                Invoke-Command -Session $session -ArgumentList $entry.node -ErrorAction Stop -ScriptBlock { param($node) Suspend-ClusterNode -Cluster smal-localbox01 -Name $node -Drain -ErrorAction Stop | Out-Null }
                $state.rpcReturned = $true; $state.outcome = 'rpc-returned-await-independent-observation'; Save-R2Worker 'rpc-returned'
                $state.postReadSucceeded = $false
                $afterDrain = Read-ComputeSnapshot
                $ids = @($plan.transitionContract.deviceOwners.PSObject.Properties | Where-Object Value -CEQ $entry.node | ForEach-Object Name)
                $devices = @($afterDrain.clusterHealth.devices | Where-Object owner -CEQ $entry.node)
                Assert-Compute ($ids.Count -eq 8 -and $devices.Count -eq 8 -and @($devices | Where-Object maintenance -NE $true).Count -eq 0) 'Automatic eight-device maintenance not verified; no node stop permitted'
                if ($entry.node -ceq 'LB-NODE01') {
                    $placements=@($afterDrain.nodeCapacity.Values | ForEach-Object {$_.bridgePlacement} | Where-Object id -IEQ '4c6ca5cc-8c9a-499b-8ffe-c029bbfd3522')
                    if ($placements.Count -ne 1 -or $placements[0].state -cne 'Running' -or $placements[0].hciNode -ceq 'LB-NODE01') { throw 'Infrastructure migration not independently established' }
                }
                $proof = @{ selectedNode = $entry.node; rpcReturned = $true; eightDevicesMaintenanceVerified = $true; deviceIds = $ids; planSha256 = $planSha; sourceCommit = $sourceCommit; key = $effectKey }
                Assert-ComputeMaintenanceHealth $afterDrain $entry.node $proof $false
                $bytes = [Text.UTF8Encoding]::new($false).GetBytes(($proof | ConvertTo-Json -Compress))
                $p = Join-Path $root ('drain-proof-' + $entry.node + '.json')
                $s = [IO.File]::Open($p, [IO.FileMode]::CreateNew, [IO.FileAccess]::Write, [IO.FileShare]::Read)
                try { $s.Write($bytes, 0, $bytes.Length); $s.Flush($true) } finally { $s.Dispose() }
                $state.drainProof = $proof
                $state.postReadSucceeded = $true
            }
            'resume' {
                # Do not wait for Healthy or resync before this compensating return to service.
                Invoke-Command -Session $session -ArgumentList $entry.node -ErrorAction Stop -ScriptBlock { param($node) Resume-ClusterNode -Cluster smal-localbox01 -Name $node -Failback NoFailback -ErrorAction Stop | Out-Null }
            }
            { $_ -cin @('moc-remove','moc-add') } {
                $expectedBinding = $plan.mocContract.nodes.PSObject.Properties[$mocObserver].Value
                $rpc = Invoke-Command -Session $session -ArgumentList $entry.node, $mocObserver, $entry.effect, $expectedBinding, @($entry.beforeMocMembers), $ProfileMocRead.ToString(), $plan.mocContract.membershipIdentity -ErrorAction Stop -ScriptBlock {
                    param($node, $peer, $effect, $binding, $beforeMembers, $readSource, $identityBinding)
                    $exactPeers=@{'LB-NODE02'='LB-NODE01';'LB-NODE03'='LB-NODE01';'LB-NODE01'='LB-NODE02'}
                    if($peer -cne $exactPeers[$node] -or $peer -ceq $node -or $env:COMPUTERNAME -cne $peer){throw 'MOC executing hostname/peer differs or equals target; no fallback'}
                    $ErrorActionPreference = 'Stop'
                    $read = & ([ScriptBlock]::Create($readSource)) $peer $false $identityBinding
                    if ($read.observerNode -cne $peer -or $binding.observerNode -cne $peer -or $read.qualified -ne $true -or $read.membershipObserved -ne $true) { throw 'Actual MOC membership identity is not qualified' }
                    if ((@($read.members | Sort-Object) -join '|') -cne (@($beforeMembers | Sort-Object) -join '|')) { throw 'Actual MOC membership changed before mutation' }
                    foreach ($name in @('Get-MocNode','Remove-MocPhysicalNode','New-MocPhysicalNode')) {
                        if ($read.commands[$name].contractSha256 -cne $binding.commands.PSObject.Properties[$name].Value.contractSha256) { throw 'Installed MOC binding changed before mutation' }
                    }
                    $name = if ($effect -ceq 'moc-remove') { 'Remove-MocPhysicalNode' } elseif ($effect -ceq 'moc-add') { 'New-MocPhysicalNode' } else { throw 'Unknown exact MOC effect' }
                    $command = @(Get-Command -Name $name -All -ErrorAction Stop)
                    if ($command.Count -ne 1 -or $command[0].ModuleName -cne $binding.commands.PSObject.Properties[$name].Value.moduleName) { throw 'MOC mutation binding is not unique/pinned' }
                    & $command[0] -NodeName $node | Out-Null
                    @{ rpcReturned = $true; node = $node; executingPeer = $peer; effect = $effect }
                }
                Assert-Compute ($rpc.rpcReturned -eq $true -and $rpc.node -ceq $entry.node -and $rpc.executingPeer -ceq $mocObserver -and $rpc.effect -ceq $entry.effect) 'Exact MOC mutation return missing'
                $state.rpcReturned = $true; $state.outcome = 'rpc-returned-await-independent-observation'; Save-R2Worker 'rpc-returned'
                $state.postReadSucceeded = $false
                $mocAfter = Read-ProfileMoc $mocObserver
                $state.mocObservation = $mocAfter
                Assert-ProfileMocMembership $mocAfter $entry.afterMocMembers $plan.mocContract
                $state.mocMembership = @($mocAfter.members); $state.postReadSucceeded = $true
            }
            'guest-start' {
                $vm=Get-VM -Id $plan.guestIds.PSObject.Properties[$entry.node].Value
                if ($vm.Name -cne $entry.node -or $vm.State.ToString() -cne 'Off') { throw 'Exact independently admitted Off guest required' }
                if ($before.hostCapacity.freeMemoryBytes -lt ($entry.targetMemoryBytes+32GB)) { throw 'Physical start availability/outer reserve violated' }
                Start-VM -VM $vm -ErrorAction Stop
            }
            'infrastructure-return' {
                Invoke-Command -Session $session -ErrorAction Stop -ScriptBlock {
                    Move-ClusterVirtualMachineRole -Cluster smal-localbox01 -VMId '4c6ca5cc-8c9a-499b-8ffe-c029bbfd3522' -Node LB-NODE01 -MigrationType Live -ErrorAction Stop | Out-Null
                }
            }
            'complete' {
                $placements=@($before.nodeCapacity.Values | ForEach-Object {$_.bridgePlacement} | Where-Object id -IEQ '4c6ca5cc-8c9a-499b-8ffe-c029bbfd3522')
                if ($placements.Count -ne 1 -or $placements[0].state -cne 'Running' -or $placements[0].hciNode -cne 'LB-NODE01') { throw 'Final infrastructure owner differs' }
                foreach($guest in $before.guestsStatic) {
                    $wanted=if($guest.name -ceq 'LB-DC01'){@{cpu=2;memory=4GB}}else{$target[$guest.name]}
                    if ($guest.cpu -ne $wanted.cpu -or $guest.memory -ne $wanted.memory -or $before.states[$guest.name] -cne 'Running') { throw 'Final mixed profile/state differs' }
                }
                $proof=@{planSha256=$planSha;sourceCommit=$sourceCommit;allHealthyAndOk=$true;noActiveStorageJobs=$true;finalProfiles=$entry.beforeProfiles;allOriginalOperationsReconciled=$true;predecessorHandoffSha256=$plan.predecessorHandoff.recordSha256;predecessorPlanSha256='c6b4dfdfb3e1170129c8d578d3a87794d9ec41142275ed69c5decc2fb6006d53'}
                [IO.File]::WriteAllText((Join-Path $root 'completion.json'),($proof|ConvertTo-Json -Depth 20 -Compress))
                $operation=Get-Content (Join-Path $root 'operation.json') -Raw|ConvertFrom-Json
                $operation.active=$false
                [IO.File]::WriteAllText((Join-Path $root 'operation.json'),($operation|ConvertTo-Json -Depth 20 -Compress))
            }
            default { throw 'Unlisted one-effect stage' }
        }
        $state.rpcReturned = $true
        $state.outcome = 'rpc-returned-await-independent-observation'
    } finally {
        # Return is not effect convergence. Original intent and PID persist after exceptions.
        Save-R2Worker 'returned'
    }
} catch {
    if ($state.rpcReturned -eq $true -and $state.postReadSucceeded -eq $false) { $state.outcome = 'rpc-returned-postread-failed-await-independent-observation' }
    $state.errorType = $_.Exception.GetType().Name; $state.errorLine = $_.InvocationInfo.ScriptLineNumber
    if (-not $state.rpcInvoked) { $state.outcome = 'precondition-refused-no-rpc'; Save-R2Worker 'returned' }
    else { Save-R2Worker $state.phase }
} finally {
    if ($session) { Remove-PSSession $session }
    if ($held) { $mutex.ReleaseMutex() }; $mutex.Dispose()
}
